#!/usr/bin/env python3
"""Edit the 36 rendered WanGP clips + finished audio into output/terafab_full_movie.mp4.

  python scripts/assemble_movie.py [--burn-subs]

* Refuses to run if any shot is missing or failed its motion check (no placeholders, no stills).
* Each clip: trimmed to 5.0 s, cropped/upscaled (Lanczos) to 1920x1080, 30 fps, shared teal/amber grade.
* Overlays added here (never generated by the model): scene concept labels, a persistent
  "AI-GENERATED VISUALIZATION" notice, and the end title over a fade to black.
* Audio: audio/terafab_mix.wav (narration + original score + SFX, -14 LUFS) -> AAC 192 kbps.
* Then writes output/thumbnail.png and output/render_report.md with QC diagnostics.
"""
import argparse
import json
import platform
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
W, H, FPS = 1920, 1080, 30
GRADE = ("eq=contrast=1.06:saturation=1.08:gamma=0.98,"
         "colorbalance=rs=-0.04:gs=-0.01:bs=0.05:rh=0.05:gh=0.01:bh=-0.04,vignette=PI/5")


def run(cmd, **kw):
    print(">", " ".join(map(str, cmd))[:220], flush=True)
    return subprocess.run(list(map(str, cmd)), check=True, **kw)


def font():
    for f in ("C:/Windows/Fonts/arialbd.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
              "/System/Library/Fonts/Supplemental/Arial Bold.ttf"):
        if Path(f).exists():
            return f
    sys.exit("No bold font found; edit font() in assemble_movie.py")


def esc(p):
    return str(p).replace("\\", "/").replace(":", r"\:").replace("'", r"\'")


def text_filter(tmp, name, text, fnt, size, x, y, t0, t1, alpha="1", box=True):
    tf = tmp / f"{name}.txt"
    tf.write_text(text, encoding="utf-8")
    b = ":box=1:boxcolor=black@0.45:boxborderw=14" if box else ""
    return (f"drawtext=fontfile='{esc(fnt)}':textfile='{esc(tf)}':fontsize={size}:fontcolor=white"
            f":alpha='{alpha}'{b}:x={x}:y={y}:enable='between(t,{t0},{t1})'")


def probe(path):
    j = json.loads(subprocess.run(["ffprobe", "-v", "error", "-show_entries",
                                   "stream=codec_type,codec_name,width,height,r_frame_rate,sample_rate,channels:format=duration",
                                   "-of", "json", str(path)], capture_output=True, text=True, check=True).stdout)
    return j


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--burn-subs", action="store_true", help="Also burn the SRT into the picture")
    ap.add_argument("--manifest", type=Path, default=ROOT / "project/scene_manifest.json")
    a = ap.parse_args()
    m = json.loads(a.manifest.read_text(encoding="utf-8"))
    shots = [sh for sc in m["scenes"] for sh in sc["shots"]]
    missing = [sh["id"] for sh in shots if sh["status"] != "done" or not sh.get("output")
               or not (ROOT / sh["output"]).exists()]
    if missing:
        sys.exit(f"Not all shots are rendered with verified motion: {missing}\n"
                 "Run scripts/render_scenes.py first. No placeholders will be used.")
    mix = ROOT / "audio/terafab_mix.wav"
    if not mix.exists():
        sys.exit("audio/terafab_mix.wav missing — run scripts/make_audio.py")
    fnt = font()
    out = ROOT / "output"
    out.mkdir(exist_ok=True)
    tmp = Path(tempfile.mkdtemp(prefix="terafab_"))
    try:
        # 1. normalise every shot (5.0 s, 1920x1080 lanczos, 30 fps, grade)
        norm = []
        for sh in shots:
            n = tmp / f"{sh['id']}.mp4"
            vf = (f"trim=0:5,setpts=PTS-STARTPTS,scale={W}:{H}:force_original_aspect_ratio=increase:flags=lanczos,"
                  f"crop={W}:{H},fps={FPS},{GRADE},setsar=1,format=yuv420p")
            run(["ffmpeg", "-y", "-v", "error", "-i", ROOT / sh["output"], "-vf", vf, "-an",
                 "-c:v", "libx264", "-preset", "medium", "-crf", "16", "-r", FPS, n])
            norm.append(n)
        lst = tmp / "list.txt"
        lst.write_text("".join(f"file '{p.as_posix()}'\n" for p in norm), encoding="utf-8")
        joined = tmp / "joined.mp4"
        run(["ffmpeg", "-y", "-v", "error", "-f", "concat", "-safe", "0", "-i", lst, "-c", "copy", joined])

        # 2. overlays + end title + audio
        total = 180.0
        f = [text_filter(tmp, "aigen", "AI-GENERATED VISUALIZATION", fnt, 22, "w-tw-36", "h-th-30",
                         0, total - 3, alpha="0.75", box=False)]
        for sc in m["scenes"]:
            if sc["overlay"] and sc["scene"] != 18:
                f.append(text_filter(tmp, f"ov{sc['scene']}", sc["overlay"], fnt, 34, 60, 56,
                                     sc["start"] + 0.3, sc["end"] - 0.2))
        f.append(f"fade=t=out:st={total - 3.2}:d=2.2")
        title_alpha = f"min(1,(t-{total - 2.6})/0.6)"
        f.append(text_filter(tmp, "title", "TERAFAB — THE FUTURE OF AI CHIPS?", fnt, 72, "(w-tw)/2",
                             "(h-th)/2-50", total - 2.6, total, alpha=title_alpha, box=False))
        f.append(text_filter(tmp, "cta", "WHAT DO YOU THINK?", fnt, 44, "(w-tw)/2", "(h-th)/2+60",
                             total - 2.1, total, alpha=f"min(1,(t-{total - 2.1})/0.5)", box=False))
        if a.burn_subs:
            f.append("subtitles=output/terafab_captions.srt:force_style='FontName=Arial,FontSize=20,"
                     "Outline=2,MarginV=60'")
        final = out / "terafab_full_movie.mp4"
        run(["ffmpeg", "-y", "-v", "error", "-i", joined, "-i", mix, "-filter_complex",
             f"[0:v]{','.join(f)}[v]", "-map", "[v]", "-map", "1:a", "-t", total,
             "-c:v", "libx264", "-preset", "slow", "-crf", "17", "-profile:v", "high", "-pix_fmt", "yuv420p",
             "-r", FPS, "-c:a", "aac", "-b:a", "192k", "-ar", 48000, "-movflags", "+faststart", final], cwd=ROOT)

        # 3. thumbnail from a wafer shot
        pick = next((sh for sh in shots if sh["id"] == "s05b"), shots[0])
        tf = [text_filter(tmp, "th1", "TERAFAB", fnt, 190, 70, 120, 0, 9, box=False).replace(
                  "fontcolor=white", "fontcolor=white:borderw=8:bordercolor=black@0.8"),
              text_filter(tmp, "th2", "THE CHIP RACE", fnt, 96, 78, 330, 0, 9, box=False).replace(
                  "fontcolor=white", "fontcolor=0xFFB347:borderw=6:bordercolor=black@0.8"),
              text_filter(tmp, "th3", "CONCEPT VISUALIZATION", fnt, 30, 80, "h-80", 0, 9)]
        run(["ffmpeg", "-y", "-v", "error", "-ss", "2.5", "-i", ROOT / pick["output"], "-frames:v", "1", "-vf",
             f"scale=1280:720:force_original_aspect_ratio=increase:flags=lanczos,crop=1280:720,{GRADE},"
             f"eq=contrast=1.15:saturation=1.2,{','.join(tf)}", out / "thumbnail.png"])
    finally:
        shutil.rmtree(tmp, ignore_errors=True)

    # 4. QC + report
    info = probe(final)
    bd = subprocess.run(["ffmpeg", "-v", "info", "-t", "176", "-i", str(final), "-vf",
                         "blackdetect=d=0.1:pix_th=0.08", "-an", "-f", "null", "-"],
                        capture_output=True, text=True).stderr
    blacks = re.findall(r"black_start:([\d.]+) black_end:([\d.]+)", bd)
    lo = subprocess.run(["ffmpeg", "-hide_banner", "-nostats", "-i", str(final), "-vn", "-af", "ebur128=peak=true",
                         "-f", "null", "-"], capture_output=True, text=True).stderr
    summary = lo[lo.rfind("Summary:"):]
    loud = re.search(r"I:\s+(-?[\d.]+) LUFS", summary)
    peak = re.search(r"Peak:\s+(-?[\d.]+) dBFS", summary)
    v = next(s for s in info["streams"] if s["codec_type"] == "video")
    au = next((s for s in info["streams"] if s["codec_type"] == "audio"), None)

    rows = []
    for sc in m["scenes"]:
        for sh in sc["shots"]:
            last = sh["attempts"][-1] if sh["attempts"] else {}
            p = last.get("probe") or {}
            rows.append(f"| {sh['id']} | {sc['title']} | {sh['settings_used']['model_type']} "
                        f"{sh['settings_used']['resolution']} | {sh['seed']} | {len(sh['attempts'])} | "
                        f"{p.get('duration', '?')} s @ {p.get('fps', '?')} fps | {sh.get('motion_score')} | "
                        f"{last.get('seconds', '?')} s |")
    vt = json.loads((ROOT / "project/vo_timings.json").read_text(encoding="utf-8"))
    report = f"""# Render report — TERAFAB documentary

## Final file
- `output/terafab_full_movie.mp4`: {v['codec_name']} {v['width']}x{v['height']} @ {v['r_frame_rate']} fps, \
duration {float(info['format']['duration']):.2f} s
- Audio: {au['codec_name'] if au else 'MISSING'} {au.get('sample_rate') if au else ''} Hz, \
{au.get('channels') if au else ''} ch, integrated {loud.group(1) if loud else '?'} LUFS, true peak {peak.group(1) if peak else '?'} dBFS
- Black frames before the end-title fade (threshold 0.1 s): {'none' if not blacks else blacks}
- Subtitles: `output/terafab_captions.srt` (sentence timings measured from the synthesized narration)
- Credits spent: **0**: all video rendered locally with WanGP; narration (Kokoro-82M, Apache-2.0),
  score and SFX were synthesized locally by `scripts/make_audio.py`.

## Per-shot results (36 x 5 s WanGP motion clips -> 18 x 10 s chapters)
Motion score = mean absolute luma change between consecutive frames (0-255); clips under 0.5
or with more than 50% frozen frames are rejected and re-rendered.

| Shot | Scene | Model / resolution | Seed | Attempts | Clip | Motion | Render time |
|---|---|---|---|---|---|---|---|
{chr(10).join(rows)}

## Narration timing
{chr(10).join(f"- Scene {s['scene']:02d}: starts {s['vo_start']} s, lasts {s['vo_duration']} s (speed {s['speed']})" for s in vt['scenes'])}
"""
    (out / "render_report.md").write_text(report, encoding="utf-8")
    print(f"\n✓ {final}\n✓ {out / 'thumbnail.png'}\n✓ {out / 'render_report.md'}")


if __name__ == "__main__":
    main()
